def second_largest(items):
    distinct_elements = []
    for item in items:
        if item not in distinct_elements:
            distinct_elements.append(item)

    if len(distinct_elements) < 2:
        return None

    max_val = None
    second_max = None

    for val in distinct_elements:
        if max_val is None or val > max_val:
            second_max = max_val
            max_val = val
        elif val < max_val and (second_max is None or val > second_max):
            second_max = val

    return second_max
